    return any(x in private_collections() for x in collections)


def extract_year(input: str, int_only: bool = True) -> str:
    """Extracts the year from an author's birth or death date."""
    if int_only:
        pattern = r'\d{4}'
    else:
        pattern = r'[0-9xX?]{4}'

    if result := re.search(pattern, input):
        return result.group()

    return ''


