def load(
    rec: dict,
    account_key=None,
    from_marc_record: bool = False,
    save: bool = True,
) -> dict:
    """Given a record, tries to add/match that edition in the system.

    Record is a dictionary containing all the metadata of the edition.
    The following fields are mandatory:

        * title: str
        * source_records: list

    :param dict rec: Edition record to add
    :param bool from_marc_record: whether the record is based on a MARC record.
    :rtype: dict
    :return: a dict to be converted into a JSON HTTP response, same as load_data()
    """
    if not is_promise_item(rec):
        validate_record(rec)

    normalize_import_record(rec)

    # Resolve an edition if possible, or create and return one if not.
    edition_pool = build_pool(rec)
    if not edition_pool:
        # No match candidates found, add edition
        return load_data(rec, account_key=account_key, save=save)

    match = find_match(rec, edition_pool)
    if not match:
        # No match found, add edition
        return load_data(rec, account_key=account_key, save=save)

    # We have an edition match at this point
    need_work_save = need_edition_save = False
    work: dict[str, Any]
    existing_edition: Edition | dict = web.ctx.site.get(match)
    if not save:
        existing_edition = _record_dict(existing_edition)
        existing_edition.setdefault('key', match)

    # check for, and resolve, author redirects
    resolved_authors = []
    for author_ref in existing_edition.get('authors', []) or []:
        author_key = (
            author_ref.get('key')
            if isinstance(author_ref, dict)
            else getattr(author_ref, 'key', None)
        )
        author = (
            author_ref
            if not isinstance(author_ref, dict) and is_redirect(author_ref)
            else web.ctx.site.get(author_key)
        )
        seen_author_keys = set()
        while author and is_redirect(author):
            if author.key in seen_author_keys:
                break
            seen_author_keys.add(author.key)
            author = web.ctx.site.get(author.location)
        if author:
            resolved_authors.append({'key': author.key})
    if resolved_authors:
        existing_edition['authors'] = resolved_authors

    # Send revision 1 promise item editions to the same pipeline as new editions
    # because we want to overwrite most of their data.
    if should_overwrite_promise_item(
        edition=existing_edition, from_marc_record=from_marc_record
    ):
        return load_data(
            rec,
            account_key=account_key,
            existing_edition=existing_edition,
            save=save,
        )

    existing_works = existing_edition.get('works') or []
    if existing_works:
        work_key = (
            existing_works[0].get('key')
            if isinstance(existing_works[0], dict)
            else existing_works[0].key
        )
        work = _record_dict(web.ctx.site.get(work_key))
        work_created = False
    else:
